"><span class=\"zone-dot\" aria-hidden=\"true\"></span><span>B/C <small>${resume ? '이어서 진행' : '벨트 컨베이어'}</small></span></button>\n    <div class=\"overview-caption\" hidden><p>벨트 컨베이어 · 이물질 제거 작업</p><h1>마지막 자물쇠</h1><p>작업반장의 지시를 받았습니다.<br>작업 전에 무엇부터 하겠습니까?</p><span class=\"overview-instruction\">${resume ? 'B/C 구역을 선택하면 이전 단계와 위치에서 이어갑니다.' : '표시된 B/C 구역을 선택해 현장으로 이동하세요.'}</span></div>`;\n  root.replaceChildren(figure);\n  const img = figure.querySelector('img');\n  const loading = figure.querySelector('.overview-loading');\n  const button = figure.querySelector('.zone-button');\n  const caption = figure.querySelector('.overview-caption');\n  let destroyed = false;\n  const loaded = () => { if (destroyed) return; loading.remove(); button.hidden = false; caption.hidden = false; };\n  const failed = () => {\n    if (destroyed) return;\n    loading.innerHTML = '<strong>공장 전경을 불러오지 못했습니다.</strong><p>이미지 경로와 서버 연결을 확인한 뒤 다시 불러오세요.</p><button type=\"button\">다시 불러오기</button>';\n    loading.querySelector('button').addEventListener('click', () => { img.src = `${img.src.split('?')[0]}?retry=${Date.now()}`; });\n  };\n  img.addEventListener('load', loaded); img.addEventListener('error', failed);\n  button.addEventListener('click', onEnter);\n  if (img.complete && img.naturalWidth > 0) loaded();\n  return { destroy() { destroyed = true; img.removeEventListener('load', loaded); img.removeEventListener('error', failed); button.removeEventListener('click', onEnter); figure.remove(); } };\n}\n:root{color-scheme:dark;--base:#202927;--panel:#26322e;--ink:#edf0e9;--muted:#a7b4ad;--line:#52615b;--accent:#ffc857;--danger:#e57668;--safe:#abd7bb;font-family:\"Malgun Gothic\",\"Apple SD Gothic Neo\",sans-serif;font-synthesis:none}\n*{box-sizing:border-box}body{margin:0;background:#17201e;color:var(--ink)}button,input{font:inherit}button{cursor:pointer;border:1px solid var(--line);background:var(--panel);color:var(--ink);padding:11px 16px;border-radius:5px;font-weight:700;line-height:1.35}bu