const mime = { '.html': 'text/html; charset=utf-8', '.css': 'text/css; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.mjs': 'text/javascript; charset=utf-8', '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.webp': 'image/webp', '.json': 'application/json; charset=utf-8', '.txt': 'text/plain; charset=utf-8' };

class RequestError extends Error {
  constructor(status) { super('요청을 처리할 수 없습니다.'); this.status = status; }
}

function json(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' });
  response.end(JSON.stringify(body));
}

function readBody(request) {
  return new Promise((accept, reject) => {
    let size = 0;
    let settled = false;
    const chunks = [];
    request.on('data', (chunk) => {
      if (settled) return;
      size += chunk.length;
      if (size > 8192) {
        settled = true;
        chunks.length = 0;
        reject(new RequestError(413));
      } else chunks.push(chunk);
    });
    request.on('end', () => {
      if (!settled) accept(Buffer.concat(chunks).toString('utf8'));
    });
    request.on('error', () => { if (!settled) reject(new RequestError(400)); });
    request.on('aborted', () => { if (!settled) reject(new RequestError(400)); });
  });
}

async function supplement(run, config, signal) {
  const result = judgeEntry(run);
  const fixed = fixedExplanation(result);
  if (!config.apiKey) return fixed;
  const first = sentences(fixed.text)[0];
  const timeout = AbortSignal.timeout(8000);
  try {
    const response = await config.providerFetch('https://api.openai.com/v1/responses', {
      method: 'POST',
      headers: { Authorization: `Bearer ${config.apiKey}`, 'Content-Type': 'application/json' },
      signal: AbortSignal.any([signal, timeout]),
      body: JSON.stringify({
        model: config.model,
        store: false,
        max_output_tokens: 320,
        instructions: '한국어 안전교육 보충 설명을 정확히 세 문장으로 작성합니다. 코드의 판정은 변경할 수 없습니다. 첫 문장은 입력의 고정 첫 문장을 그대로 사용하고, 마지막 문장은 입력의 고정 마지막 문장을 그대로 사용합니다. 둘째 문장에서 정지와 에너지 차단의 차이, 개인 잠금·표지, 잔류 에너지 처리 또는 차단 확인의 원칙 하나를 설명합니다. 판정, 성공, 실패, 작업 허가, 현장 인증, 조치 생략을 주장하지 않습니다. 입력 밖의 현장 절차나 통계를 만들지 않습니다.',
        input: JSON.stringify({ kind: result.kind, safety: run.safety, firstSentence: first, lastSentence: sentences(fixed.text)[2] }),
      }),
    });
    if (!response.ok) return fixed;
    const data = await response.json();
    const text = (Array.isArray(data.output) ? data.output : [])
      .filter((item) => item.type === 'message' && Array.isArray(item.content))
      .flatMap((item) => item.content)
      .filter((item) => item.type === 'output_text' && typeof item.text === 'string')
      .map((item) => item.text).join(' ').trim().replace(/\s+/gu, ' ');
    return validSupplement(text, fixed) ? { source: 'ai', text } : fixed;
  } catch {
    return fixed;
  }
}

async function serveFile(pathname, response) {
  let filename = publicFiles.get(pathname);
  const isDraftAsset = pathname.startsWith(prefix + 'assets/');
  if (isDraftAsset && /^assets\/(?:[\p{L}\p{N}_-]+\/)*[\p{L}\p{N}_.-]+\.(?:png|jpe?g|webp|json)$/u.test(pathname.slice(prefix.length))) {
    filename = pathname.slice(prefix.length);
  }
  if (!filename) throw new RequestError(404);
  let canonical;
  let allowedRoot;
  try {
    [canonical, allowedRoot] = await Promise.all([
      realpath(resolve(draftRoot, filename)), realpath(pathname.startsWith(prefix) ? draftRoot : projectRoot),
    ]);
  } catch { throw new RequestError(404); }
  const localPath = relative(allowedRoot, canonical);
  if (localPath === '..' || localPath.startsWith('..' + sep) || resolve(allowedRoot, localPath) !== canonical) throw new RequestError(404);
  const mappedPath = pathname.startsWith(prefix) ? filename : relative(projectRoot, resolve(draftRoot, filename));
  if (canonical !== resolve(allowedRoot, mappedPath)) throw new RequestError(404);
  const body = await readFile(canonical);
  response.writeHead(200, { 'Content-Type': mime[extname(canonical)], 'X-Content-Type-Options': 'nosniff', 'Cache-Control': 'no-cache' });
  response.end(body);
}

export function makeServer({ apiKey = process.env.OPENAI_API_KEY ?? '', model = process.env.OPENAI_MODEL || 'gpt-4.1-mini', providerFetch = globalThis.fetch } = {}) {
  const config = { apiKey, model, providerFetch };
  return createServer(async (request, response) => {
    try {
      const pathname = decodeURIComponent((request.url ?? '').split('?')[0]);
      if (pathname.includes('\\') || pathname.includes('\0') || pathname.split('/').some((part) => part === '.' || part === '..')) throw new RequestError(400);
      if (pathname === '/' && request.method === 'GET') {
        response.writeHead(302, { Location: encodeURI(prefix) + '?ai=on' });
        response.end();
      } else if (pathname === prefix + 'api/feedback') {
        if (request.method !== 'POST') throw new RequestError(405);
        if (!/^application\/json(?:\s*;|$)/iu.test(request.headers['content-type'] ?? '')) throw new RequestError(415);
        if (Number(request.headers['content-length']) > 8192) { request.resume(); throw new RequestError(413); }
        let run;
        try { run = runFromPayload(JSON.parse(await readBody(request))); }
        catch (error) { throw error instanceof RequestError ? error : new RequestError(400); }
        const controller = new AbortController();
        response.once('close', () => { if (!response.writableEnded) controller.abort(); });
        const explanation = await supplement(run, config, controller.signal);
        if (!response.destroyed) json(response, 200, explanation);
      } else {
        if (request.method !== 'GET') throw new RequestError(405);
        await serveFile(pathname, response);
      }
    } catch (error) {
      const status = error instanceof RequestError ? error.status : error instanceof URIError ? 400 : 500;
      if (!response.headersSent && !response.destroyed) json(response, status, { error: '요청을 처리할 수 없습니다.' });
      else if (!response.destroyed) response.end();
    }
  });
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const port = Number(process.env.PORT || 8780);
  if (!Number.isInteger(port) || port < 1 || port > 65535) throw new Error('PORT는 1~65535 정수여야 합니다.');
  makeServer().listen(port, '127.0.0.1', () => {
    console.log(`SAFEPLAY 초안: http://127.0.0.1:${port}${encodeURI(prefix)}?ai=on`);
  });
}
# SAFEPLAY 작업자 시점 플레이 초안

독립 초안의 작업자는 컨베이어 이물질 제거를 맡는다. 작업반장이 “컨베이어 밑에 있는 이물질을 제거하세요”라고 지시하고, 첫 질문은 “작업 시작 전에 무엇을 하겠습니까?”이다. 전체 공장뷰에서 B/C를 선택하면 안전한 위치에서 시작한다. 현장 이동과 대상 조사를 거쳐 여섯 질문을 순서대로 해결한다.

이번 변경은 사용자가 요청한 로컬 게임 수정이다. 커밋·푸시·스테이징·fetch·pull·stash·reset을 수행하지 않는다. 기존 루트 구현·문서·vendor·reference는 수정 범위 밖이다. 변경 전후 `git status`와 소유 파일의 `git diff`를 확인하고 동시 작업자의 변경은 보존한다.

## 실행 계획과 책임

1. 규칙 담당: `src/scenario.mjs`의 여섯 단계·24개 보기·단계별 결과·상태 계약을 구현하고 `tests/scenario.test.mjs`로 검증한다.
2. 앱 담당: `src/app.js`에서 현재 질문의 네 보기, 행동 결과 확인, 같은 단계 재도전, 완료 흐름을 연결한다.
3. 현장 담당: `src/stage.js`의 이동·대상 배치·행동 애니메이션을 연결한다. 장면은 규칙의 결과를 표현하며 판정하지 않는다.
4. 피드백 담당: 서버와 고정 설명을 새 전송 객체 및 순수 재판정에 맞춘다.
5. 통합 확인: 소유 파일별 diff·Node 검사 후 실제 브라우저에서 여섯 단계, 서로 다른 오답, 되감기, 재연습, 공장 왕복을 검증한다. 실제로 확인한 항목만 QA 기록에 남긴다.

기술은 저장소의 Phaser 4.2.1, HTML/CSS, JavaScript ES 모듈 및 Node 기본 모듈이다. 공장뷰는 기존 전경을 읽는다. 현장 배경과 작업자 시트는 `assets/assets.json`의 측정값으로 배치하며, 생성 이력은 `assets/generation-prompts.md`와 걷기 자료의 별도 프롬프트 기록에 있다. `reference/`에서 런타임 import하지 않는다.

## 독립 함수 계약

`src/scenario.mjs`는 DOM·Phaser·통신 없이 다음을 제공한다. 다른 루트 시나리오의 계약과 독립적인 초안 계약이다.

- `STEPS`: 읽기 전용 여섯 단계. `{id,title,targetId,question,options}`이며 각 `options`는 고유한 네 보기, 정답 한 개다. 보기는 `{id,text,correct,effect,title,explanation,actionCaption,animation}`이다. 정답의 위치는 `[2,0,3,1,2,0]`으로 달라진다.
- 단계 순서: 설비 정지 → 오퍼레이터 전달 → MCC 차단·본인 잠금 → 태그아웃 → 잔류 에너지 안전조치·트라이아웃 → 이물질 제거.
- `SAFETY_STEPS`: 화면에 표시할 `{key,label}` 여섯 개. `stopped`, `notified`, `locked`, `tagged`, `verified`, `cleaned`다.
- `TARGETS`: `{id,title,text,fact}` 세 개. `control` 조작반·연락, `energy-isolator` MCC 차단·잠금, `work-access` 점검구. 단계별 대상은 `control → control → energy-isolator → energy-isolator → control → work-access`다.
- `createRun()`: `{stepIndex:0,observed:Set,attempts:0,rewinds:0,completed:false,safety,pending:null}`. 안전조치 객체는 `stopped`, `notified`, `isolated`, `lockPresent`, `locked`, `tagged`, `residualCleared`, `verified`, `cleaned`의 아홉 불리언이며 처음에는 모두 false다.
- `inspect(run,targetId)`: 유효한 대상을 관찰 Set에 기록하고 대상 내용을 반환한다. 조사만으로 안전조치가 완료되지 않는다.
- `getCurrentStep(run)`: 현재 단계를 반환한다. 완료하면 null이다. `getPendingOutcome(run)`은 아직 확인하지 않은 선택의 결과를 복원하며, 대기가 없으면 null이다.
- `chooseOption(run,optionId)`: 현재 단계의 유효한 선택에서만 `attempts`를 한 번 증가시킨다. 정답은 해당 단계의 안전조치를 반영하고 `pending:{stepId,optionId,kind:'progress'}`를 만든다. 오답은 이전 체크포인트의 안전조치를 유지하며 `pending.kind='wrong'`을 만든다. 다른 단계·완료·결과 확인 대기 중에는 `blocked`, 알 수 없는 ID는 어떤 변경보다 먼저 RangeError다.
- 결과 형식은 `{kind,effect,title,reason,explanation,actionCaption,animation,stepId,optionId}`다. `kind`는 `progress`, `wrong`, `blocked`, `success`; 선택별 `effect`는 `safe-action`, `accident`, `notice`, `mismatch`, `unidentified`, `unverified`, `paused`다. 차단 응답에는 선택 ID나 애니메이션이 없을 수 있다.
- `acknowledgeOutcome(run)`: 정답 결과 확인 뒤에만 `stepIndex`를 증가시킨다. 마지막 정답 확인에서 `stepIndex=6`, `completed=true`, `kind='success'`가 된다. 비사고 오답 확인은 pending만 해제하고 같은 질문으로 돌아간다. 사고 결과는 이 함수로 해제할 수 없다.
- `rewind(run)`: 사고 오답에서만 pending을 해제하고 `rewinds`를 증가시킨다. 선택 전 단계·안전조치와 관찰·시도 기록을 유지한다. 사고 장면에서 실행한 위험 분기는 설명용 표현이며, 정상 진행의 체크포인트를 덮어쓰지 않는다.
- `judgeEntry(run)`: 순수 재판정이다. 여섯 단계와 아홉 안전조치가 완료되면 `success`, 아니면 `wrong`과 작업 보류 설명을 반환한다. 미완료 상태만으로 사고를 만들지 않으며 횟수·완료 상태를 변경하지 않는다.
- `serializeRun(run)`: Set을 배열로 바꾸고 안전조치·pending을 복사한 JSON 전송 객체를 검증하여 반환한다. `runFromPayload(payload)`는 독립된 Set과 객체를 복원한다.

정상 상태 변화는 `stopped → notified → isolated+lockPresent+locked → tagged → residualCleared+verified → cleaned`다. 다음 단계는 결과 확인까지 끝나야 선택할 수 있다. 두 번 클릭하거나 결과 창에서 다른 보기를 골라도 시도 횟수는 늘지 않는다. 다시 연습은 `createRun()`으로 모든 기록과 조치를 초기화한다.

전송 검증은 정확한 필드·허용 ID·중복 없는 조사 배열·불리언·0~1,000,000 정수 횟수·0~6 단계 번호를 요구한다. 안전조치는 확인된 단계의 정확한 접두 상태와 같아야 하며, 정답 pending이면 현재 단계 조치만 추가한다. pending의 단계·보기·종류는 현재 질문과 일치해야 한다. 완료 플래그는 단계 6과 동치이고, 시도·되감기 횟수의 하한 및 상호 관계도 검증한다. 알 수 없는 필드, 과거·미래 pending, 허위 완료와 모순된 상태를 거부한다.

서버는 검증한 상태로 `judgeEntry`를 호출하며 클라이언트 결과 문자열을 판정 근거로 사용하지 않는다. 정답 대기 상태의 이물질 제거는 아직 완료로 인정하지 않는다. 이 상태 검증은 행동 이력 인증이나 성적 저장 기능이 아니다. AI는 규칙 결과를 바꾸지 않고 보충 설명만 제공한다.

## 시뮬레이션 가정과 현장 확인

이 초안은 예시 설비의 선택형 실습이며 승인된 실제 작업 절차가 아니다. 구체적인 전압·MCC 내부 작업·무자격 조작 방법을 안내하지 않는다. 대상 에너지와 차단 지점, 잠금 위치, 잔류 에너지 처리, 트라이아웃 방법, 작업 권한은 해당 설비의 현장 절차로 확인해야 한다.

오답은 선택별 결과를 갖는다. 불통보는 작업 인지 누락과 재가동 오인 우려, 다른 설비 잠금은 대상 불일치, 타인 잠금 의존은 본인 보호 누락, 잘못된 표지는 식별 정보 오류, 트라이아웃 누락은 유효성 미확인, 시험 중 움직임은 차단 이상 발견으로 표현한다. 표지 누락 자체가 설비를 기동시키지 않는다. 사고는 운전 중 접근, 차단 전 접근, 부적합 체결 후 진입, 작업 전 잠금 해제 후 진입의 네 가지 위험 행동 분기에서만 재현한다. 작업 범위 밖 행동과 재가동 요청은 실제 접근·재가동 전에 보류한다.

## 현재 규칙 검증

시나리오 Node 검사 14개가 통과했다. 여섯 단계·각 네 보기·정답 위치, 18개 오답의 서로 다른 설명과 결과, 결과 확인 전 진행 차단, 중복 입력의 단일 기록, 잘못된 ID의 무변경, 전체 완료, 사고 되감기 기록 유지, 새 실습 초기화, 순수 재판정, 모든 pending JSON 왕복 및 허위 상태 거부를 확인한다. 이번 통합의 브라우저 검증과 서버 검사 결과는 담당자가 실제 실행 후 QA 기록으로 확정한다. 이전 자유 행동 버전의 QA 결과를 이번 버전의 확인으로 재사용하지 않는다.
# 마지막 자물쇠 — 6단계 행동 선택 체험

공장 전경에서 B/C 구역을 선택하면 조작반 근처에서 작업을 시작합니다. 작업반장이 “컨베이어 밑에 있는 이물질을 제거하세요.”라고 지시하고, “작업을 시작하기 전에 무엇을 하겠습니까?”라는 질문을 제시합니다.

진행 순서는 **설비 정지 → 오퍼레이터 전달 → MCC 개인 잠금 → 태그아웃 → 트라이아웃 → 이물질 제거**입니다. 단계마다 선택지는 정확히 네 개이며 정답은 하나입니다. 행동을 선택하면 현장 화면에서 그 행동과 상황 변화를 먼저 보여주고 설명 카드를 엽니다. 정답은 ‘다음 단계’로 진행하며, 오답은 선택별 위험을 확인한 뒤 같은 단계에서 다시 선택합니다. 사고가 발생하는 선택에만 사고 재현과 되감기를 적용합니다.

현장 절차를 검토하기 위한 교육 초안입니다. 실제 차단 대상, 잔류 에너지 처리, 작업 방법은 승인된 현장 절차를 따릅니다.

저장소 루트에서 실행합니다. 기본 체험은 npm 설치나 API 키가 필요하지 않습니다.

```powershell
python -m http.server 8770 --bind 127.0.0.1
```

브라우저에서 <http://127.0.0.1:8770/권기봉/초안/>을 엽니다. Phaser는 저장소의 `vendor/phaser.min.js`를 사용합니다. 현장 배경·작업자 자산은 초안 폴더에 있으며 공장 전경과 반장 역할 이미지는 기존 공용 이미지 경로에서 읽습니다.

- 좌우 방향키 또는 A / D: 이동
- 화면 화살표: 누르고 있는 동안 이동, 짧은 클릭 또는 Enter / Space로 한 걸음 이동
- E 또는 현장 행동 선택 버튼: 현재 단계의 위치에서 네 가지 행동 열기
- 선택 화면의 1–4: 해당 행동 선택
- ‘현장 보기’ 또는 선택 화면의 Escape: 현장으로 돌아가기
- 설명 카드: ‘다음 단계’ 또는 ‘다시 선택’으로 확인 후 진행
- 사고 카드: ‘되감기’로 선택 직전으로 복귀. 이전 단계의 안전조치와 기록 유지
- ‘공장 전경’: 위치·단계·안전조치·선택 결과·횟수를 유지하고, B/C 선택 시 이어가기
- ‘다시 연습’: 위치·단계·안전조치·입력·모달·타이머·횟수·설명 요청 초기화
- ‘움직임 줄이기’: 사고 흔들림·깜박임과 행동 효과를 줄이고 결과 설명 유지

선택적 AI 보충 설명 서버는 Node.js 22 이상에서 실행합니다.

```powershell
node 권기봉/초안/server.mjs
```

<http://127.0.0.1:8780/권기봉/초안/>에서 체험합니다. URL에 `?ai=on`을 붙이면 최종 결과의 보충 설명을 요청합니다. `OPENAI_API_KEY`는 서버 환경변수로만 설정합니다. `OPENAI_MODEL`과 `PORT`도 서버 환경변수로 설정할 수 있습니다. 키가 없거나 요청에 실패하면 고정 설명을 사용합니다. 단계 진행과 판정은 코드 규칙이 결정합니다.

규칙 및 서버 검사는 저장소 루트에서 실행합니다.

```powershell
node 권기봉/초안/tests/scenario.test.mjs
node 권기봉/초안/tests/server.test.mjs
node --test 권기봉/초안/tests/motion.test.mjs
```

초안 변경은 `권기봉/초안` 안에서 진행합니다. 사용자의 명시적인 요청 없이 커밋하거나 푸시하지 않습니다.
