function showTraining(courseId) {
  const course = CATALOG.find(item => item.courseId === courseId);
  if (!course || !run.completed) return;
  cancelExplanation();
  const answer = trainingChecks.get(courseId);
  openDialog('training', `<div class="debrief-header"><span class="dialog-kicker">추천 교육</span><h2 id="dialog-title">${escapeHtml(course.title)}</h2><p>짧은 설명을 읽고 한 가지 행동을 선택하세요.</p></div><div class="debrief-scroll training-content">${course.lesson.map(paragraph => `<p class="dialog-copy">${escapeHtml(paragraph)}</p>`).join('')}<h3>${escapeHtml(course.question.prompt)}</h3><div class="option-list">${course.question.options.map((option, index) => `<button type="button" data-training-option="${index}" ${answer?.index === index ? 'aria-pressed="true"' : 'aria-pressed="false"'}><span class="option-letter">${String.fromCharCode(65 + index)}</span><span>${escapeHtml(option)}</span><kbd>${index + 1}</kbd></button>`).join('')}</div>${answer ? `<div class="training-feedback ${answer.correct ? 'correct' : 'retry'}" role="status"><strong>${answer.correct ? '확인했습니다.' : '다시 확인해 보세요.'}</strong><p>선택한 행동: ${escapeHtml(course.question.options[answer.index])}</p><p>${escapeHtml(course.question.explanation)}</p></div>` : '<p class="choice-guide">숫자 키 1–4로도 선택할 수 있습니다. 교육 문제는 게임 기록을 바꾸지 않습니다.</p>'}</div><div class="debrief-footer"><button id="back-to-result" class="primary" type="button">분석 결과로 돌아가기</button></div>`);
  dialogContent.querySelector('#back-to-result').addEventListener('click', showResult);
  dialogContent.querySelectorAll('[data-training-option]').forEach(button => button.addEventListener('click', () => {
    const index = Number(button.dataset.trainingOption);
    trainingChecks.set(courseId, { index, correct: index === course.question.correctIndex });
    showTraining(courseId);
    dialogContent.querySelector('.training-feedback')?.scrollIntoView({ block: 'nearest', behavior: 'instant' });
  }));
}
function saveLearningRecord() {
  if (!learningReport || !run.completed) return;
  const data = exportLearningRecord(learningReport);
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a'); link.href = url; link.download = 'safeplay-learning-record.json';
  document.body.append(link); link.click(); link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  announce('익명 선택 기록과 추천 교육 ID를 JSON으로 저장했습니다.');
}
EOF
