/* Completion is a centered learning journal; short outcomes keep their field view. */
dialog[data-kind='result'], dialog[data-kind='training'] {
  width: min(1060px, calc(var(--scene-width) - 64px));
  height: calc(var(--scene-height) - 80px);
  max-height: calc(var(--scene-height) - 80px);
  inset: 50% auto auto 50%; transform: translate(-50%, -50%);
  overflow: hidden; border-color: #8296a1; background: #172129fa;
}
dialog[data-kind='result']::backdrop, dialog[data-kind='training']::backdrop { background: #101b29a3; }
dialog[data-kind='result'] .dialog-inner, dialog[data-kind='training'] .dialog-inner { height: 100%; min-height: 0; display: flex; flex-direction: column; padding: 0; }
.debrief-header { flex-shrink: 0; padding: 22px 32px 17px; text-align: center; border-bottom: 1px solid #536772; }
.debrief-header h2 { font-size: 29px; line-height: 1.32; margin: 8px 0 10px; letter-spacing: -.8px; }
.debrief-header p { margin: 0; font-size: 14px; color: #d0dce2; line-height: 1.6; }
.debrief-scroll { flex: 1; min-height: 0; overflow-y: auto; overscroll-behavior: contain; padding: 20px 32px 24px; scrollbar-color: #8699a3 #27333a; }
.debrief-footer { flex-shrink: 0; display: flex; justify-content: center; align-items: center; flex-wrap: wrap; gap: 10px; padding: 15px 24px; background: #1c2932; border-top: 1px solid #617782; }
.debrief-footer button { font-size: 14px; }
.debrief-metrics { display: flex; flex-wrap: wrap; gap: 20px 34px; padding-bottom: 18px; color: #c7d3da; font-size: 13px; }
.debrief-metrics strong { margin-left: 8px; font-size: 23px; color: var(--ink); }
dialog[data-kind='result'] .panel-safety { grid-template-columns: repeat(3, 1fr); gap: 10px 20px; margin: 0 0 20px; padding-bottom: 20px; border-bottom: 1px solid #536772; }
.debrief-explanation { margin-bottom: 24px; }
.learning-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 20px; }
.learning-heading h3 { font-size: 21px; margin: 0 0 12px; }
.learning-heading span { font-size: 12px; color: #c4d9e2; }
.learning-summary { margin: 0 0 22px; font-size: 15px; line-height: 1.8; color: #e2e8eb; }
