+:root {
+  color-scheme: dark;
+  --base: #172129; --panel: #27333a; --ink: #f2ede3; --muted: #c0cbd0;
+  --line: #62717a; --accent: #e7b642; --guide: #77a5b6; --danger: #d46046; --safe: #b9d3c1;
+  --scene-width: min(100vw, calc(100dvh * 16 / 9));
+  --scene-height: min(100dvh, calc(100vw * 9 / 16));
+  --scene-left: calc((100vw - var(--scene-width)) / 2);
+  --scene-top: calc((100dvh - var(--scene-height)) / 2);
+  font-family: 'Malgun Gothic', 'Noto Sans KR', 'Apple SD Gothic Neo', sans-serif;
+  font-synthesis: none;
+}
+* { box-sizing: border-box; }
+body { margin: 0; min-height: 100dvh; display: grid; place-items: center; background: #10171c; color: var(--ink); overflow: hidden; }
+button, input { font: inherit; }
+button { cursor: pointer; border: 1px solid var(--line); background: var(--panel); color: var(--ink); padding: 11px 16px; border-radius: 3px; font-weight: 700; line-height: 1.4; min-height: 48px; }
+button:hover { border-color: var(--accent); background: #35434c; }
+button:disabled { cursor: default; opacity: .55; }
+button.primary { background: var(--accent); color: #172129; border-color: var(--accent); }
+button.primary:hover { background: #f4cd70; }
+button:focus-visible, input:focus-visible { outline: 3px solid #ffe191; outline-offset: 3px; }
+[hidden] { display: none !important; }
+.app-shell { position: relative; width: var(--scene-width); height: var(--scene-height); isolation: isolate; }
+.game-shell, .scene-root { position: relative; width: 100%; height: 100%; overflow: hidden; background: var(--base); }
+.app-header { position: absolute; inset: 16px 22px auto; display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; z-index: 8; pointer-events: none; }
+.brand { color: white; font-size: 15px; font-weight: 900; letter-spacing: -.3px; text-shadow: 0 2px 5px #0009; }
+.brand small { display: block; margin-top: 4px; font-size: 11px; font-weight: 500; color: var(--ink); letter-spacing: 0; }
+.app-shell[data-view='stage'] .brand, .app-shell[data-view='loading'] .brand { visibility: hidden; }
+.header-tools { display: flex; align-items: center; gap: 12px; padding: 7px 9px; background: #172129e8; pointer-events: auto; border-radius: 3px; }
+.motion-setting, .text-setting { font-size: 12px; display: flex; align-items: center; gap: 6px; cursor: pointer; color: var(--ink); min-height: 36px; }
+input { accent-color: var(--accent); width: 16px; height: 16px; margin: 0; }
+.quiet-button { background: transparent; padding: 5px 9px; font-size: 12px; }
+.overview-scene { position: absolute; inset: 0; background: var(--base); z-index: 6; overflow: hidden; }
+.overview-scene.leaving { opacity: 0; transition: opacity 240ms ease-out; pointer-events: none; }
+.overview-world { position: absolute; inset: 0; transform-origin: 24.1% 27.3%; transition: transform 900ms cubic-bezier(.2,.65,.2,1); }
+.overview-image { width: 100%; height: 100%; object-fit: cover; display: block; }
+.overview-scene::after { content: ''; position: absolute; inset: 0; background: linear-gradient(0deg, #122029d9, transparent 49%); pointer-events: none; z-index: 1; transition: background 900ms; }
+.overview-markers { position: absolute; inset: 0; }
+.location-marker { position: absolute; transform: translate(-50%, -50%); display: flex; align-items: center; gap: 7px; padding: 7px 11px; background: #27333adc; color: #f4f1e9; border-left: 2px solid #9eadb4; font-size: 13px; line-height: 1.4; white-space: nowrap; pointer-events: none; box-shadow: 0 2px 8px #0003; }
+.location-pin { width: 7px; height: 7px; border: 1px solid #d2dbe0; transform: rotate(45deg); }
+.zone-button { position: absolute; z-index: 2; transform: translate(-50%,-50%); display: flex; align-items: center; gap: 10px; background: #172129ef; border: 1px solid var(--accent); box-shadow: 0 0 0 5px #e7b64228, 0 4px 16px #0006; padding: 11px 15px; white-space: nowrap; text-align: left; font-size: 17px; }
+.zone-button:hover { background: #343830; box-shadow: 0 0 0 7px #e7b64238; }
+.zone-button small { display: block; font-size: 11px; font-weight: 500; margin-top: 3px; color: #e8d79e; }
+.zone-dot { width: 10px; height: 10px; border-radius: 50%; background: var(--accent); }
+.overview-caption { position: absolute; z-index: 2; left: 5%; bottom: 10%; max-width: 420px; text-shadow: 0 2px 10px #0007; transition: opacity 240ms; }
+.overview-caption h1 { font-size: clamp(30px, 3.2vw, 48px); letter-spacing: -2px; line-height: 1.25; margin: 8px 0 15px; }
+.overview-caption p { font-size: clamp(12px, 1.15vw, 16px); line-height: 1.7; margin: 0; color: #fff; }
+.overview-caption p:first-child { color: #f4d27a; font-size: 13px; }
+.overview-instruction { display: block; margin-top: 19px; font-size: 13px; color: #e6ebed; }
+.map-legend { position: absolute; z-index: 2; bottom: 20px; right: 24px; display: flex; align-items: center; gap: 8px; font-size: 12px; margin: 0; padding: 8px 11px; background: #172129dc; color: #e2e7e9; transition: opacity 240ms; }
+.legend-active { width: 7px; height: 7px; border-radius: 50%; background: var(--accent); }
+.legend-place { width: 7px; height: 7px; margin-left: 9px; border: 1px solid #d2dbe0; transform: rotate(45deg); }
+.travel-caption { position: absolute; z-index: 3; left: 5%; bottom: 9%; display: flex; flex-direction: column; gap: 8px; text-shadow: 0 2px 8px #000a; }
+.travel-caption span { font-size: 14px; color: #f4d27a; }
+.travel-caption strong { font-size: 25px; font-weight: 700; }
+.traveling .overview-world { transform: scale(3.5); }
+.traveling .overview-markers, .traveling .overview-caption, .traveling .map-legend { opacity: 0; pointer-events: none; }
+.traveling::after { background: linear-gradient(0deg, #101b29e6, #17212935 60%); }
+.motion-reduced .overview-world { transition: none; }
+.motion-reduced.traveling .overview-world { transform: none; }
+.overview-loading, .scene-loading { position: absolute; inset: 0; background: var(--base); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 15px; z-index: 9; text-align: center; padding: 30px; }
+.overview-loading p, .scene-loading p { max-width: 440px; color: var(--muted); line-height: 1.7; }
+.scene-loading h2 { margin: 0; font-size: 22px; }
+.stage-host { width: 100%; height: 100%; position: absolute; inset: 0; }
+.draft-stage { position: relative; width: 100%; height: 100%; overflow: hidden; }
+.stage-canvas, .stage-canvas canvas { width: 100% !important; height: 100% !important; display: block; }
+.stage-hud { position: absolute; top: 18px; left: 22px; z-index: 3; pointer-events: none; max-width: 58%; }
+.stage-heading { padding: 10px 13px; background: #172129e8; border-left: 3px solid var(--accent); }
+.stage-heading strong { display: block; font-size: 16px; }
+.stage-heading small { display: block; margin-top: 6px; font-size: 13px; color: #dae2e6; line-height: 1.6; white-space: pre-line; }
+.safety-hud { position: absolute; bottom: 20px; left: 22px; z-index: 3; pointer-events: none; display: flex; flex-direction: column; gap: 10px; max-width: 65%; }
+.safety-progress { background: #172129de; padding: 9px 12px; }
+.safety-progress p { margin: 0 0 7px; font-size: 11px; color: var(--muted); }
+.safety-progress p strong { color: var(--ink); margin-left: 8px; }
+.safety-list { display: flex; gap: 9px; list-style: none; padding: 0; margin: 0; }
+.safety-list li { font-size: 0; color: #a7b4bc; display: flex; align-items: center; gap: 5px; }
+.safety-list li.current { font-size: 12px; color: #f1d789; }
+.step-mark { display: inline-flex; align-items: center; justify-content: center; min-width: 20px; min-height: 20px; font-size: 11px; border: 1px solid #839099; }
+.safety-list .done .step-mark { border-color: var(--safe); color: var(--safe); }
+.safety-list .current .step-mark { border-color: var(--accent); color: var(--accent); }
+.field-status { display: flex; gap: 16px; padding-left: 3px; text-shadow: 0 1px 4px #000; }
+.location-chip, .run-counters { font-size: 11px; color: #edf0ef; }
+.run-counters strong { color: var(--ink); margin: 0 3px 0 7px; }
+.stage-controls { position: absolute; bottom: 20px; right: 22px; z-index: 4; display: flex; align-items: center; gap: 7px; }
